class Agent:
    def __init__(self, name):
        self.name = name
    def greet(self):
        return f"Агент {self.name}"

class Spy(Agent):
    def greet(self):
        return f"Тихо. {self.name}"

a = Agent("V")
s = Spy("Ричард")
print(a.greet())
print(s.greet())

